void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float progress = texture(iChannel0, vec2(0.5)).x;
    vec2 p = uv - vec2(1.0, 0.0);
    float angle = atan(p.y, p.x);
    float dist = length(p);
    float page = smoothstep(0.0, 1.0, (angle + 3.14159) / 6.28318);
    float mask = smoothstep(progress, progress + 0.1, page);
    vec4 tex1 = texture(iChannel1, uv);
    vec4 tex2 = texture(iChannel2, uv);
    fragColor = mix(tex1, tex2, mask);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float progress = mod(iTime, 2.0) / 2.0;
    fragColor = vec4(progress);
}
